function CalendarEventForm({allowedTypes,save,back}) {
  const [v,setV]=useState({type:allowedTypes[0],title:'',date:'',day:'',time:'',location:'',description:''});
  const set=(key,value)=>setV({...v,[key]:value});
  const submit=()=>{
    const day=Number(v.date.slice(-2));
    if(!v.title.trim()||!v.date.trim()||!v.time.trim()||!v.location.trim()||!v.description.trim())return Alert.alert('Missing information','Add the event name, date, time, location and details.');
    if(!clubModel.validDate(v.date))return Alert.alert('Event date','Use a valid date in YYYY-MM-DD format.');
    save({...v,iso:v.date,id:`${v.type.toLowerCase().replace(/\s+/g,'-')}-${Date.now()}`,day,committeeOnly:v.type==='Committee meeting',automaticReminder:true});
  };
  return <><DetailHeader title={allowedTypes.length===1?'Create social event':'Create meeting'} back={back}/><ScrollView style={s.sheet} contentContainerStyle={s.content} keyboardShouldPersistTaps="handled"><Text style={s.hero}>{allowedTypes.length===1?'New social event':'New AGM or committee meeting'}</Text><Text style={s.body}>The event will appear in both the chronological list and calendar view.</Text>{allowedTypes.length>1&&<><Text style={s.fieldLabel}>Event type</Text><View style={s.choiceWrap}>{allowedTypes.map(type=><Choice key={type} label={type} active={v.type===type} onPress={()=>set('type',type)}/>)}</View></>}<Field label="Event name" value={v.title} onChangeText={x=>set('title',x)}/><Field label="Event date (YYYY-MM-DD)" value={v.date} onChangeText={x=>set('date',x)} placeholder="2027-03-20"/><Field label="Day number for calendar view" value={v.day} onChangeText={x=>set('day',x.replace(/[^0-9]/g,''))} keyboardType="number-pad" placeholder="20"/><Field label="Time" value={v.time} onChangeText={x=>set('time',x)} placeholder="19:00"/><Field label="Location" value={v.location} onChangeText={x=>set('location',x)} placeholder="Venue or meeting room"/><Field label="Event details" value={v.description} onChangeText={x=>set('description',x)} multiline/><View style={s.info}><Text style={s.infoTitle}>Visibility and reminder</Text><Text style={s.bodySmall}>{v.type==='Committee meeting'?'Only committee roles will see this event and its 10am reminder.':'All members will see this event and receive a friendly 10am reminder on the event date.'} Members can respond Yes or No; accepting adds the event to their phone calendar.</Text></View><TouchableOpacity style={s.primary} onPress={submit}><Text style={s.buttonText}>Publish event</Text></TouchableOpacity></ScrollView></>;
}

function JoinTripPreferencesByDay({trip,userName,value,save,back}) { const days=[];for(let d=new Date(trip.startDate+'T12:00:00Z');d<=new Date(trip.endDate+'T12:00:00Z')&&days.length<31;d.setUTCDate(d.getUTCDate()+1))days.push(d.toISOString().slice(0,10)); const [climbingRole,setClimbingRole]=useState(value.climbingRole||'');const [sameThroughout,setSameThroughout]=useState(value.sameThroughout!==false); const [day,setDay]=useState(days[0]); const [partner,setPartner]=useState(value.partner||''); const [dayPartners,setDayPartners]=useState(value.dayPartners||{}); const [openToMix,setOpenToMix]=useState(value.openToMix!==false); const choose=name=>sameThroughout?setPartner(name):setDayPartners({...dayPartners,[day]:name}); const selected=sameThroughout?partner:dayPartners[day]; const clear=()=>sameThroughout?setPartner(''):setDayPartners({...dayPartners,[day]:''}); const submit=()=>save({climbingRole,partner:sameThroughout?partner:'',decideLater:sameThroughout?!partner:days.some(d=>!dayPartners[d]),openToMix,sameThroughout,dayPartners:sameThroughout?Object.fromEntries(days.map(d=>[d,partner])):dayPartners}); return <><DetailHeader title="Climbing preferences" back={back}/><ScrollView style={s.sheet} contentContainerStyle={s.content}><Text style={s.hero}>Who are you climbing with?</Text><Text style={s.body}>Record your preferred climbing partner for the trip. The organiser can then use this when creating the final groups.</Text><Text style={s.fieldLabel}>What would you like to do?</Text><View style={s.choiceWrap}>{(trip.types.includes('Bouldering')?['Find a climbing partner','Boulder independently','Discuss with organiser']:['Lead','Second / top-rope','Find a climbing partner','Discuss with organiser']).map(label=><Choice key={label} label={label} active={climbingRole===label} onPress={()=>setClimbingRole(label)}/>)}</View><Text style={s.hint}>This is a preference, not a competence approval.</Text><Toggle label="Same partner throughout the trip" value={sameThroughout} setValue={setSameThroughout}/>{!sameThroughout&&<View style={s.dayTabs}>{days.map(x=><TouchableOpacity key={x} style={[s.dayTab,day===x&&s.dayTabActive]} onPress={()=>setDay(x)}><Text style={[s.dayTabText,day===x&&s.choiceTextActive]}>{x}{dayPartners[x]?' . SET':''}</Text></TouchableOpacity>)}</View>}<Text style={s.section}>{sameThroughout?'Partner for the whole trip':`${day} partner`}</Text><View style={s.memberPicker}>{members.filter(x=>x!==userName).map(name=><TouchableOpacity key={name} style={[s.memberChoice,selected===name&&s.memberChoiceActive]} onPress={()=>choose(name)}><View style={s.smallAvatar}><Text style={s.smallAvatarText}>{initials(name)}</Text></View><Text style={[s.memberChoiceText,selected===name&&s.choiceTextActive]}>{name}</Text>{selected===name&&<Text style={s.checkMark}>YES</Text>}</TouchableOpacity>)}</View><TouchableOpacity style={[s.laterChoice,!selected&&s.memberChoiceActive]} onPress={clear}><Text style={s.laterIcon}>WAIT</Text><View style={s.grow}><Text style={s.infoTitle}>Choose later</Text><Text style={s.meta}>{sameThroughout?'The organiser will see that you need pairing.':`No partner selected yet for ${day}.`}</Text></View>{!selected&&<Text style={s.checkMark}>YES</Text>}</TouchableOpacity>{!sameThroughout&&<View style={s.info}><Text style={s.infoTitle}>Your day-by-day choices</Text><Text style={s.bodySmall}>{days.map(d=>`${d}: ${dayPartners[d]||'Choose later'}`).join('\n')}</Text></View>}<View style={s.mixCard}><Toggle label="Open to mixing partners during the trip" value={openToMix} setValue={setOpenToMix}/><Text style={s.hint}>The organiser can place you in a group of two or more and confirm each day separately.</Text></View><TouchableOpacity style={s.primary} onPress={submit}><Text style={s.buttonText}>Save climbing preferences</Text></TouchableOpacity></ScrollView></>; }
